import React, { useEffect, useState } from "react";
import { Routes, Route, Link, useNavigate } from "react-router-dom";
import axios from "axios";

import Projects from "./pages/Projects";
import Resources from "./pages/Resources";
import Profile from "./pages/Profile";

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || "http://localhost:4000",
  timeout: 8000,
});

/* ---------- Small UI helper components ---------- */

const Icon = ({ name, className = "" }) => {
  // only a few inline SVGs used for visual polish
  const icons = {
    clock: (<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.6"><circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/></svg>),
    heart: (<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.6"><path d="M20.8 6.6a4.6 4.6 0 0 0-6.5 0L12 8.9l-2.3-2.3a4.6 4.6 0 0 0-6.5 6.5L12 21l8.8-7.9a4.6 4.6 0 0 0 0-6.5z"/></svg>),
    check: (<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.6"><path d="M20 6L9 17l-5-5"/></svg>),
    star: (<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M12 .587l3.668 7.431L24 9.748l-6 5.847 1.416 8.269L12 19.771 4.584 23.864 6 15.595 0 9.748l8.332-1.73z"/></svg>)
  };
  return <span className={`icon ${className}`}>{icons[name] || null}</span>;
};

/* ---------- Topbar ---------- */

function Topbar({ user, setUser }) {
  return (
    <header className="topbar">
      <div className="brand-row container">
        <div className="brand-left">
          <div className="logo-mark">NG</div>
          <div>
            <Link to="/" className="brand-link">NextGen Health</Link>
            <div className="brand-sub">Smart Care • Thapar Project</div>
          </div>
        </div>

        <nav className="nav">
          <Link to="/">Home</Link>
          <Link to="/dashboard">Patient</Link>
          <Link to="/projects">Projects</Link>
          <Link to="/resources">Resources</Link>
          <Link to="/profile">Profile</Link>
          <Link to="/admin" className="admin-link">Admin</Link>
          {user ? (
            <button className="btn-ghost" onClick={() => { setUser(null); localStorage.removeItem('demo_user'); }}>Logout</button>
          ) : null}
        </nav>
      </div>
    </header>
  );
}

/* ---------- Home (enhanced hero) ---------- */

function Home({ onRegister, setUser }) {
  const [name, setName] = useState("");
  const [age, setAge] = useState("");
  const [contact, setContact] = useState("");
  const navigate = useNavigate();

  async function submit(e) {
    e.preventDefault();
    if (!name || !contact) return alert("Enter name and contact");
    const res = await api.post("/api/patients", { name, age, contact });
    setUser(res.data);
    localStorage.setItem("demo_user", JSON.stringify(res.data));
    onRegister(res.data);
    navigate("/dashboard");
  }

  return (
    <main className="container hero-enhanced">
      <section className="hero-card">
        <div className="hero-left">
          <h1>NextGen Health — <span className="accent">Smart Care</span></h1>
          <p className="lead">A lightweight clinic & telehealth demo for Thapar College projects — appointment booking, doctor notes, project proposals and resources in a single portal.</p>

          <div className="stats-row">
            <div className="stat">
              <div className="stat-num">120+</div>
              <div className="stat-label">Student Users</div>
            </div>
            <div className="stat">
              <div className="stat-num">45</div>
              <div className="stat-label">Project Ideas</div>
            </div>
            <div className="stat">
              <div className="stat-num">98%</div>
              <div className="stat-label">Demo Satisfaction</div>
            </div>
          </div>

          <div className="hero-actions">
            <Link to="/dashboard" className="btn hero-btn">Get Started</Link>
            <Link to="/projects" className="btn btn-outline">View Project Ideas</Link>
          </div>

          <div className="features-grid">
            <div className="feature"><Icon name="clock" /> Fast booking</div>
            <div className="feature"><Icon name="heart" /> Clinic notes</div>
            <div className="feature"><Icon name="check" /> Proposal hub</div>
          </div>
        </div>

        <aside className="hero-form card">
          <div className="pill">Quick Register</div>
          <form onSubmit={submit} className="form-compact">
            <input placeholder="Full name" value={name} onChange={e => setName(e.target.value)} />
            <input placeholder="Age" value={age} onChange={e => setAge(e.target.value)} />
            <input placeholder="Contact (e.g. +91...)" value={contact} onChange={e => setContact(e.target.value)} />
            <button className="btn full">Register & Try</button>
          </form>
          <small className="muted">Used for demo only — no real data is sent off your machine.</small>
        </aside>
      </section>

      <section className="container showcase">
        <h3>Why students love it</h3>
        <div className="card-grid cards-3">
          <div className="card feature-card">
            <div className="card-head">Project-ready templates</div>
            <div className="card-desc">Pre-built idea cards and a proposal form so you can jump straight to implementation and demo.</div>
            <div className="card-foot"><button className="btn btn-sm">Explore</button></div>
          </div>
          <div className="card feature-card">
            <div className="card-head">Admin tools</div>
            <div className="card-desc">Assign supervisors, update appointment statuses, and add medical notes for demo walkthroughs.</div>
            <div className="card-foot"><button className="btn btn-sm btn-outline">Open</button></div>
          </div>
          <div className="card feature-card">
            <div className="card-head">Presentation-ready</div>
            <div className="card-desc">Clean visuals and exportable checklists make it perfect for college project demonstration.</div>
            <div className="card-foot"><button className="btn btn-sm">Get Slides</button></div>
          </div>
        </div>
      </section>

      <section className="testimonials">
        <div className="container">
          <h3>Student reviews</h3>
          <div className="test-grid">
            <div className="testimonial card">
              <div className="muted small">Riya S. — Final year</div>
              <p className="quote">“Helped me finalize my project idea and demo quickly. Clean UI and useful templates.”</p>
            </div>
            <div className="testimonial card">
              <div className="muted small">Aman K. — Third year</div>
              <p className="quote">“Easy to show in viva — admin and patient flows explained my project well.”</p>
            </div>
            <div className="testimonial card">
              <div className="muted small">Prof. Verma</div>
              <p className="quote">“Nice prototype to evaluate student submissions — simple and focused.”</p>
            </div>
          </div>
        </div>
      </section>
    </main>
  );
}


/* ---------- Patient Dashboard (same features, nicer layout) ---------- */

function PatientDashboard({ user, refreshFlag, setRefreshFlag }) {
  const [appointments, setAppointments] = useState([]);
  const [form, setForm] = useState({
    department: "General Medicine",
    symptoms: "",
    preferredDoctor: "",
    preferredDate: "",
  });

  useEffect(() => {
    if (user) fetchAppointments();
    // eslint-disable-next-line
  }, [user, refreshFlag]);

  async function fetchAppointments() {
    try {
      const res = await api.get(`/api/appointments/patient/${user.id}`);
      setAppointments(res.data);
    } catch (e) {
      console.error(e);
      setAppointments([]);
    }
  }

  async function submit(e) {
    e.preventDefault();
    if (!form.department || !form.symptoms) return alert("Please fill required fields");
    await api.post("/api/appointments", { ...form, patientId: user.id });
    setForm({
      department: "General Medicine",
      symptoms: "",
      preferredDoctor: "",
      preferredDate: "",
    });
    setRefreshFlag((f) => f + 1);
  }

  if (!user)
    return (
      <div className="container">
        <div className="card"><p>Please register from Home to use the patient dashboard.</p></div>
      </div>
    );

  return (
    <div className="container dashboard-enhanced">
      <div className="left-col">
        <div className="card profile-card">
          <div className="muted">Signed in</div>
          <h3>{user.name}</h3>
          <div className="muted">{user.contact}</div>
          <div className="profile-stats">
            <div><strong>{appointments.length}</strong><div className="muted small">Appointments</div></div>
            <div><strong>—</strong><div className="muted small">Prescriptions</div></div>
            <div><strong>—</strong><div className="muted small">Feedback</div></div>
          </div>
        </div>

        <div className="card">
          <h4>Quick actions</h4>
          <div className="row" style={{gap:8}}>
            <Link to="/projects" className="btn btn-outline small">Look at Projects</Link>
            <Link to="/resources" className="btn btn-outline small">Resources</Link>
          </div>
        </div>
      </div>

      <div className="right-col">
        <div className="card">
          <h3>Book Appointment</h3>
          <form onSubmit={submit} className="form">
            <label>Department</label>
            <select value={form.department} onChange={(e)=>setForm(s=>({...s,department:e.target.value}))}>
              <option>General Medicine</option>
              <option>Dermatology</option>
              <option>ENT</option>
              <option>Orthopedics</option>
            </select>

            <label>Symptoms</label>
            <textarea value={form.symptoms} onChange={(e)=>setForm(s=>({...s,symptoms:e.target.value}))} />

            <label>Preferred Doctor (optional)</label>
            <input value={form.preferredDoctor} onChange={(e)=>setForm(s=>({...s,preferredDoctor:e.target.value}))} />

            <label>Preferred Date</label>
            <input placeholder="YYYY-MM-DD" value={form.preferredDate} onChange={(e)=>setForm(s=>({...s,preferredDate:e.target.value}))} />

            <div className="form-row">
              <button className="btn">Request Appointment</button>
              <button type="button" className="btn btn-outline" onClick={()=>setForm({department:"General Medicine",symptoms:"",preferredDoctor:"",preferredDate:""})}>Clear</button>
            </div>
          </form>
        </div>

        <div className="card">
          <h3>Your Appointments</h3>
          {appointments.length===0 ? <div className="muted">No appointments yet</div> : (
            <div className="list">
              {appointments.map(a => (
                <div key={a.id} className="appt-row">
                  <div>
                    <strong>{a.department}</strong>
                    <div className="muted small">{a.preferredDate || new Date(a.createdAt).toLocaleDateString()}</div>
                    <div className="muted">{a.symptoms}</div>
                  </div>
                  <div className="status">{a.status}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------- Admin Dashboard ---------- */

function AdminDashboard({ setRefreshFlag }) {
  const [appointments, setAppointments] = useState([]);

  useEffect(()=>{fetchAll();}, []);

  async function fetchAll() {
    const res = await api.get("/api/appointments");
    setAppointments(res.data);
  }

  async function assign(id, doctor) {
    if (!doctor) return alert("Enter doctor name");
    await api.put(`/api/appointments/${id}/assign`, { doctor });
    fetchAll();
    setRefreshFlag(f => f + 1);
  }

  async function setStatus(id, status) {
    await api.put(`/api/appointments/${id}/status`, { status });
    fetchAll();
    setRefreshFlag(f => f + 1);
  }

  async function saveNotes(id, notes, prescription) {
    await api.put(`/api/appointments/${id}/notes`, { notes, prescription });
    fetchAll();
    setRefreshFlag(f => f + 1);
  }

  return (
    <div className="container admin-enhanced">
      <h2>Clinic Admin</h2>
      <div className="admin-list">
        {appointments.length===0 ? <div className="muted">No appointments</div> :
          appointments.map(a => <AdminItem key={a.id} a={a} onAssign={assign} onStatus={setStatus} onNotes={saveNotes} />)}
      </div>
    </div>
  );
}

function AdminItem({ a, onAssign, onStatus, onNotes }) {
  const [doc, setDoc] = useState(a.assignedDoctor || a.preferredDoctor || "");
  const [notes, setNotes] = useState(a.notes || "");
  const [presc, setPresc] = useState(a.prescription || "");

  return (
    <div className="card admin-item">
      <div className="admin-left">
        <div className="muted small">{new Date(a.createdAt).toLocaleString()}</div>
        <h4>{a.department}</h4>
        <div className="muted">{a.symptoms}</div>
      </div>

      <div className="admin-right">
        <input placeholder="Doctor name" value={doc} onChange={e=>setDoc(e.target.value)} />
        <div className="row">
          <button className="btn" onClick={()=>onAssign(a.id, doc)}>Assign</button>
          <select value={a.status} onChange={e=>onStatus(a.id, e.target.value)}>
            {['Requested','Confirmed','In Progress','Completed','Cancelled'].map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>

        <textarea placeholder="Doctor notes" value={notes} onChange={e=>setNotes(e.target.value)} />
        <input placeholder="Prescription" value={presc} onChange={e=>setPresc(e.target.value)} />
        <div className="row">
          <button className="btn" onClick={()=>onNotes(a.id, notes, presc)}>Save Notes</button>
        </div>
      </div>
    </div>
  );
}

/* ---------- App Root ---------- */

export default function App(){
  // initialize user from localStorage so UI persists across reloads
  const saved = typeof window !== 'undefined' && localStorage.getItem('demo_user');
  const [user, setUser] = useState(saved ? JSON.parse(saved) : null);
  const [refreshFlag, setRefreshFlag] = useState(0);

  useEffect(()=> {
    if (user) localStorage.setItem('demo_user', JSON.stringify(user));
  }, [user]);

  return (
    <div className="app">
      <Topbar user={user} setUser={setUser} />
      <Routes>
        <Route path="/" element={<Home onRegister={()=>{}} setUser={setUser} />} />
        <Route path="/dashboard" element={<PatientDashboard user={user} refreshFlag={refreshFlag} setRefreshFlag={setRefreshFlag} />} />
        <Route path="/projects" element={<Projects user={user} />} />
        <Route path="/resources" element={<Resources />} />
        <Route path="/profile" element={<Profile user={user} setUser={setUser} />} />
        <Route path="/admin" element={<AdminDashboard setRefreshFlag={setRefreshFlag} />} />
        <Route path="*" element={<div className="container"><h2>Page not found</h2><p><Link to="/">Go home</Link></p></div>} />
      </Routes>

      <footer className="site-footer">
        <div className="container">
          <div>© {new Date().getFullYear()} NextGen Health — Prototype</div>
          <div className="muted">Prepared for Thapar College project demo</div>
        </div>
      </footer>
    </div>
  );
}
